declare @nonClustered bit = 0
select	@nonClustered = 1 from sys.indexes where name = 'PK_IntersectType' and type_desc = 'NONCLUSTERED'

if (@nonClustered = 1)
begin
	ALTER TABLE [dbo].[Intersect] DROP CONSTRAINT [FK_Intersect_IntersectType];
	ALTER TABLE [metrics].[AssetVersionConditionItem] DROP CONSTRAINT [FK_MetricAssetVersionConditionItem_IntersectType];
	ALTER TABLE [metrics].[RollupPathLink] DROP CONSTRAINT [FK_MetricRollupPathLink_IntersectType];

	ALTER TABLE [dbo].[IntersectType] DROP CONSTRAINT [PK_IntersectType];
	ALTER TABLE [dbo].[IntersectType] ADD CONSTRAINT [PK_IntersectType] PRIMARY KEY CLUSTERED ( [ID] ASC );

	ALTER TABLE [dbo].[Intersect] WITH CHECK ADD CONSTRAINT [FK_Intersect_IntersectType] FOREIGN KEY([IntersectTypeID]) REFERENCES [dbo].[IntersectType] ([ID]) ON DELETE CASCADE;
	ALTER TABLE [dbo].[Intersect] CHECK CONSTRAINT [FK_Intersect_IntersectType];
	ALTER TABLE [metrics].[AssetVersionConditionItem]  WITH CHECK ADD  CONSTRAINT [FK_MetricAssetVersionConditionItem_IntersectType] FOREIGN KEY([ConditionIntersectTypeID]) REFERENCES [dbo].[IntersectType] ([ID]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[AssetVersionConditionItem] CHECK CONSTRAINT [FK_MetricAssetVersionConditionItem_IntersectType];
	ALTER TABLE [metrics].[RollupPathLink]  WITH CHECK ADD  CONSTRAINT [FK_MetricRollupPathLink_IntersectType] FOREIGN KEY([IntersectTypeID]) REFERENCES [dbo].[IntersectType] ([ID]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[RollupPathLink] CHECK CONSTRAINT [FK_MetricRollupPathLink_IntersectType];
end
